
import { Render } from '../Render/Render';
import { NVector3 } from '../../../../../../../lib/NJSCore';
export class Circle {
    cv: NVector3;
    radius: number = 5;
    render: Render;
    width: number = 5;

    strokeColor: string = '';
    fillColor: string = '';
    static GetCircle(render: Render, cv: NVector3, radius: number) {
        return new Circle(render, cv, radius);
    }
    constructor(render: Render, cv: NVector3, radius: number) {
        this.cv = cv;
        this.radius = radius;
        this.render = render;
        this.render.circleList.push(this);
        this.strokeColor = `rgb(${Math.round(Math.random() * 255)},${Math.round(Math.random() * 255)},${Math.random() * 255},${(Math.random())})`;
        this.fillColor = `rgb(${Math.round(Math.random() * 255)},${Math.round(Math.random() * 255)},${Math.random() * 255},${(Math.random())})`;


    }
    public Render(ctx: CanvasRenderingContext2D) {
        // if (!this.p0 || !this.p1) { return; }

        ctx.strokeStyle = this.strokeColor;
        ctx.fillStyle = this.fillColor;

        ctx.beginPath();
        ctx.arc(this.cv.x, this.cv.y, this.radius, 0, Math.PI * 2);
        // ctx.moveTo(this.p0.v.x, this.p0.v.y);
        // ctx.lineTo(this.p1.v.x, this.p1.v.y);
        ctx.closePath();
        ctx.stroke();
        ctx.fill();
        // console.log(this.radius);

    }
}